import express from 'express';
import { createOrder, getOrders, updateOrderStatus } from '../controllers/order.controller.js';
import { protect, adminGuard } from '../middlewares/auth.middleware.js';

const router = express.Router();

router.post('/', createOrder);
router.get('/', protect, adminGuard, getOrders);

// Route to handle order status updates
router.put('/:id/status', protect, adminGuard, updateOrderStatus);

export default router;